// Field facts from PostgreSQL REL_16_STABLE and REL_18_STABLE
// src/include/nodes/{primnodes,parsenodes}.h. This allowlist is deliberately
// versioned: an unqualified engine node cannot certify an empty binding set.
fn specification(tag: &str, major: u32) -> Option<Specification> {
    use ReferenceClass::*;
    let (fields, references, children): (Fields, References, Children) = match (major, tag) {
        (16 | 18, "AGGREF") => (&["aggfnoid", "aggtype", "aggcollid", "inputcollid", "aggtranstype", "aggargtypes", "aggdirectargs", "args", "aggorder", "aggdistinct", "aggfilter", "aggstar", "aggvariadic", "aggkind", "aggpresorted", "agglevelsup", "aggsplit", "aggno", "aggtransno", "location"], &[("aggfnoid", Routine, false), ("aggtype", Type, false), ("aggcollid", Collation, false), ("inputcollid", Collation, false), ("aggtranstype", Type, false), ("aggargtypes", Type, true)], &[("aggargtypes", true), ("aggdirectargs", true), ("args", true), ("aggorder", true), ("aggdistinct", true), ("aggfilter", false)]),
        (16 | 18, "ALIAS") => (&["aliasname", "colnames"], &[], &[("colnames", true)]),
        (16 | 18, "ARRAYCOERCEEXPR") => (&["arg", "elemexpr", "resulttype", "resulttypmod", "resultcollid", "coerceformat", "location"], &[("resulttype", Type, false), ("resultcollid", Collation, false)], &[("arg", false), ("elemexpr", false)]),
        (16, "ARRAYEXPR") => (&["array_typeid", "array_collid", "element_typeid", "elements", "multidims", "location"], &[("array_typeid", Type, false), ("array_collid", Collation, false), ("element_typeid", Type, false)], &[("elements", true)]),
        (18, "ARRAYEXPR") => (&["array_typeid", "array_collid", "element_typeid", "elements", "multidims", "list_start", "list_end", "location"], &[("array_typeid", Type, false), ("array_collid", Collation, false), ("element_typeid", Type, false)], &[("elements", true)]),
        (16 | 18, "BOOLEANTEST") => (&["arg", "booltesttype", "location"], &[], &[("arg", false)]),
        (16 | 18, "BOOLEXPR") => (&["boolop", "args", "location"], &[], &[("args", true)]),
        (16 | 18, "CASEEXPR") => (&["casetype", "casecollid", "arg", "args", "defresult", "location"], &[("casetype", Type, false), ("casecollid", Collation, false)], &[("arg", false), ("args", true), ("defresult", false)]),
        (16 | 18, "CASETESTEXPR") => (&["typeId", "typeMod", "collation"], &[("typeId", Type, false), ("collation", Collation, false)], &[]),
        (16 | 18, "CASEWHEN") => (&["expr", "result", "location"], &[], &[("expr", false), ("result", false)]),
        (16 | 18, "COALESCEEXPR") => (&["coalescetype", "coalescecollid", "args", "location"], &[("coalescetype", Type, false), ("coalescecollid", Collation, false)], &[("args", true)]),
        (16 | 18, "COERCETODOMAIN") => (&["arg", "resulttype", "resulttypmod", "resultcollid", "coercionformat", "location"], &[("resulttype", Type, false), ("resultcollid", Collation, false)], &[("arg", false)]),
        (16 | 18, "COERCETODOMAINVALUE") => (&["typeId", "typeMod", "collation", "location"], &[("typeId", Type, false), ("collation", Collation, false)], &[]),
        (16 | 18, "COERCEVIAIO") => (&["arg", "resulttype", "resultcollid", "coerceformat", "location"], &[("resulttype", Type, false), ("resultcollid", Collation, false)], &[("arg", false)]),
        (16 | 18, "COLLATEEXPR") => (&["arg", "collOid", "location"], &[("collOid", Collation, false)], &[("arg", false)]),
        (16 | 18, "COMMONTABLEEXPR") => (&["ctename", "aliascolnames", "ctematerialized", "ctequery", "search_clause", "cycle_clause", "location", "cterecursive", "cterefcount", "ctecolnames", "ctecoltypes", "ctecoltypmods", "ctecolcollations"], &[("ctecoltypes", Type, true), ("ctecolcollations", Collation, true)], &[("aliascolnames", true), ("ctequery", false), ("search_clause", false), ("cycle_clause", false), ("ctecolnames", true), ("ctecoltypes", true), ("ctecoltypmods", true), ("ctecolcollations", true)]),
        (16 | 18, "CONST") => (&["consttype", "consttypmod", "constcollid", "constlen", "constvalue", "constisnull", "constbyval", "location"], &[("consttype", Type, false), ("constcollid", Collation, false)], &[]),
        (16 | 18, "CURRENTOFEXPR") => (&["cvarno", "cursor_name", "cursor_param"], &[], &[]),
        (16 | 18, "DISTINCTEXPR") => (&["opno", "opfuncid", "opresulttype", "opretset", "opcollid", "inputcollid", "args", "location"], &[("opno", Operator, false), ("opfuncid", Routine, false), ("opresulttype", Type, false), ("opcollid", Collation, false), ("inputcollid", Collation, false)], &[("args", true)]),
        (16 | 18, "FIELDSELECT") => (&["arg", "fieldnum", "resulttype", "resulttypmod", "resultcollid"], &[("resulttype", Type, false), ("resultcollid", Collation, false)], &[("arg", false)]),
        (16 | 18, "FROMEXPR") => (&["fromlist", "quals"], &[], &[("fromlist", true), ("quals", false)]),
        (16 | 18, "FUNCEXPR") => (&["funcid", "funcresulttype", "funcretset", "funcvariadic", "funcformat", "funccollid", "inputcollid", "args", "location"], &[("funcid", Routine, false), ("funcresulttype", Type, false), ("funccollid", Collation, false), ("inputcollid", Collation, false)], &[("args", true)]),
        (16 | 18, "GROUPINGFUNC") => (&["args", "refs", "cols", "agglevelsup", "location"], &[], &[("args", true), ("refs", true), ("cols", true)]),
        (16 | 18, "GROUPINGSET") => (&["kind", "content", "location"], &[], &[("content", true)]),
        (16 | 18, "INFERENCEELEM") => (&["expr", "infercollid", "inferopclass"], &[("infercollid", Collation, false), ("inferopclass", OperatorClass, false)], &[("expr", false)]),
        (16 | 18, "JOINEXPR") => (&["jointype", "isNatural", "larg", "rarg", "usingClause", "join_using_alias", "quals", "alias", "rtindex"], &[], &[("larg", false), ("rarg", false), ("usingClause", true), ("join_using_alias", false), ("quals", false), ("alias", false)]),
        (16 | 18, "MINMAXEXPR") => (&["minmaxtype", "minmaxcollid", "inputcollid", "op", "args", "location"], &[("minmaxtype", Type, false), ("minmaxcollid", Collation, false), ("inputcollid", Collation, false)], &[("args", true)]),
        (16 | 18, "NAMEDARGEXPR") => (&["arg", "name", "argnumber", "location"], &[], &[("arg", false)]),
        (16 | 18, "NEXTVALUEEXPR") => (&["seqid", "typeId"], &[("seqid", Relation, false), ("typeId", Type, false)], &[]),
        (16 | 18, "NULLIFEXPR") => (&["opno", "opfuncid", "opresulttype", "opretset", "opcollid", "inputcollid", "args", "location"], &[("opno", Operator, false), ("opfuncid", Routine, false), ("opresulttype", Type, false), ("opcollid", Collation, false), ("inputcollid", Collation, false)], &[("args", true)]),
        (16 | 18, "NULLTEST") => (&["arg", "nulltesttype", "argisrow", "location"], &[], &[("arg", false)]),
        (16 | 18, "ONCONFLICTEXPR") => (&["action", "arbiterElems", "arbiterWhere", "constraint", "onConflictSet", "onConflictWhere", "exclRelIndex", "exclRelTlist"], &[("constraint", Constraint, false)], &[("arbiterElems", true), ("arbiterWhere", false), ("onConflictSet", true), ("onConflictWhere", false), ("exclRelTlist", true)]),
        (16 | 18, "OPEXPR") => (&["opno", "opfuncid", "opresulttype", "opretset", "opcollid", "inputcollid", "args", "location"], &[("opno", Operator, false), ("opfuncid", Routine, false), ("opresulttype", Type, false), ("opcollid", Collation, false), ("inputcollid", Collation, false)], &[("args", true)]),
        (16 | 18, "PARAM") => (&["paramkind", "paramid", "paramtype", "paramtypmod", "paramcollid", "location"], &[("paramtype", Type, false), ("paramcollid", Collation, false)], &[]),
        (16, "QUERY") => (&["commandType", "querySource", "canSetTag", "utilityStmt", "resultRelation", "hasAggs", "hasWindowFuncs", "hasTargetSRFs", "hasSubLinks", "hasDistinctOn", "hasRecursive", "hasModifyingCTE", "hasForUpdate", "hasRowSecurity", "isReturn", "cteList", "rtable", "rteperminfos", "jointree", "mergeActionList", "mergeUseOuterJoin", "targetList", "override", "onConflict", "returningList", "groupClause", "groupDistinct", "groupingSets", "havingQual", "windowClause", "distinctClause", "sortClause", "limitOffset", "limitCount", "limitOption", "rowMarks", "setOperations", "constraintDeps", "withCheckOptions", "stmt_location", "stmt_len"], &[("constraintDeps", Constraint, true)], &[("utilityStmt", false), ("cteList", true), ("rtable", true), ("rteperminfos", true), ("jointree", false), ("mergeActionList", true), ("targetList", true), ("onConflict", false), ("returningList", true), ("groupClause", true), ("groupingSets", true), ("havingQual", false), ("windowClause", true), ("distinctClause", true), ("sortClause", true), ("limitOffset", false), ("limitCount", false), ("rowMarks", true), ("setOperations", false), ("constraintDeps", true), ("withCheckOptions", true)]),
        (18, "QUERY") => (&["commandType", "querySource", "canSetTag", "utilityStmt", "resultRelation", "hasAggs", "hasWindowFuncs", "hasTargetSRFs", "hasSubLinks", "hasDistinctOn", "hasRecursive", "hasModifyingCTE", "hasForUpdate", "hasRowSecurity", "hasGroupRTE", "isReturn", "cteList", "rtable", "rteperminfos", "jointree", "mergeActionList", "mergeTargetRelation", "mergeJoinCondition", "targetList", "override", "onConflict", "returningOldAlias", "returningNewAlias", "returningList", "groupClause", "groupDistinct", "groupingSets", "havingQual", "windowClause", "distinctClause", "sortClause", "limitOffset", "limitCount", "limitOption", "rowMarks", "setOperations", "constraintDeps", "withCheckOptions", "stmt_location", "stmt_len"], &[("constraintDeps", Constraint, true)], &[("utilityStmt", false), ("cteList", true), ("rtable", true), ("rteperminfos", true), ("jointree", false), ("mergeActionList", true), ("mergeJoinCondition", false), ("targetList", true), ("onConflict", false), ("returningList", true), ("groupClause", true), ("groupingSets", true), ("havingQual", false), ("windowClause", true), ("distinctClause", true), ("sortClause", true), ("limitOffset", false), ("limitCount", false), ("rowMarks", true), ("setOperations", false), ("constraintDeps", true), ("withCheckOptions", true)]),
        (16, "RANGETBLENTRY") => (&["rtekind", "relid", "relkind", "rellockmode", "tablesample", "perminfoindex", "subquery", "security_barrier", "jointype", "joinmergedcols", "joinaliasvars", "joinleftcols", "joinrightcols", "join_using_alias", "functions", "funcordinality", "tablefunc", "values_lists", "ctename", "ctelevelsup", "self_reference", "coltypes", "coltypmods", "colcollations", "enrname", "enrtuples", "alias", "eref", "lateral", "inh", "inFromCl", "securityQuals"], &[("relid", Relation, false), ("coltypes", Type, true), ("colcollations", Collation, true)], &[("tablesample", false), ("subquery", false), ("joinaliasvars", true), ("joinleftcols", true), ("joinrightcols", true), ("join_using_alias", false), ("functions", true), ("tablefunc", false), ("values_lists", true), ("coltypes", true), ("coltypmods", true), ("colcollations", true), ("alias", false), ("eref", false), ("securityQuals", true)]),
        (18, "RANGETBLENTRY") => (&["alias", "eref", "rtekind", "relid", "inh", "relkind", "rellockmode", "perminfoindex", "tablesample", "subquery", "security_barrier", "jointype", "joinmergedcols", "joinaliasvars", "joinleftcols", "joinrightcols", "join_using_alias", "functions", "funcordinality", "tablefunc", "values_lists", "ctename", "ctelevelsup", "self_reference", "coltypes", "coltypmods", "colcollations", "enrname", "enrtuples", "groupexprs", "lateral", "inFromCl", "securityQuals"], &[("relid", Relation, false), ("coltypes", Type, true), ("colcollations", Collation, true)], &[("alias", false), ("eref", false), ("tablesample", false), ("subquery", false), ("joinaliasvars", true), ("joinleftcols", true), ("joinrightcols", true), ("join_using_alias", false), ("functions", true), ("tablefunc", false), ("values_lists", true), ("coltypes", true), ("coltypmods", true), ("colcollations", true), ("groupexprs", true), ("securityQuals", true)]),
        (16 | 18, "RANGETBLFUNCTION") => (&["funcexpr", "funccolcount", "funccolnames", "funccoltypes", "funccoltypmods", "funccolcollations", "funcparams"], &[("funccoltypes", Type, true), ("funccolcollations", Collation, true)], &[("funcexpr", false), ("funccolnames", true), ("funccoltypes", true), ("funccoltypmods", true), ("funccolcollations", true), ("funcparams", true)]),
        (16 | 18, "RANGETBLREF") => (&["rtindex"], &[], &[]),
        (16 | 18, "RANGEVAR") => (&["catalogname", "schemaname", "relname", "inh", "relpersistence", "alias", "location"], &[], &[("alias", false)]),
        (16 | 18, "RELABELTYPE") => (&["arg", "resulttype", "resulttypmod", "resultcollid", "relabelformat", "location"], &[("resulttype", Type, false), ("resultcollid", Collation, false)], &[("arg", false)]),
        (16, "ROWCOMPAREEXPR") => (&["rctype", "opnos", "opfamilies", "inputcollids", "largs", "rargs"], &[("opnos", Operator, true), ("opfamilies", OperatorFamily, true), ("inputcollids", Collation, true)], &[("opnos", true), ("opfamilies", true), ("inputcollids", true), ("largs", true), ("rargs", true)]),
        (18, "ROWCOMPAREEXPR") => (&["cmptype", "opnos", "opfamilies", "inputcollids", "largs", "rargs"], &[("opnos", Operator, true), ("opfamilies", OperatorFamily, true), ("inputcollids", Collation, true)], &[("opnos", true), ("opfamilies", true), ("inputcollids", true), ("largs", true), ("rargs", true)]),
        (16 | 18, "ROWEXPR") => (&["args", "row_typeid", "row_format", "colnames", "location"], &[("row_typeid", Type, false)], &[("args", true), ("colnames", true)]),
        (16 | 18, "ROWMARKCLAUSE") => (&["rti", "strength", "waitPolicy", "pushedDown"], &[], &[]),
        (16 | 18, "RTEPERMISSIONINFO") => (&["relid", "inh", "requiredPerms", "checkAsUser", "selectedCols", "insertedCols", "updatedCols"], &[("relid", Relation, false), ("checkAsUser", Role, false)], &[("selectedCols", true), ("insertedCols", true), ("updatedCols", true)]),
        (16 | 18, "SCALARARRAYOPEXPR") => (&["opno", "opfuncid", "hashfuncid", "negfuncid", "useOr", "inputcollid", "args", "location"], &[("opno", Operator, false), ("opfuncid", Routine, false), ("hashfuncid", Routine, false), ("negfuncid", Routine, false), ("inputcollid", Collation, false)], &[("args", true)]),
        (16 | 18, "SETOPERATIONSTMT") => (&["op", "all", "larg", "rarg", "colTypes", "colTypmods", "colCollations", "groupClauses"], &[("colTypes", Type, true), ("colCollations", Collation, true)], &[("larg", false), ("rarg", false), ("colTypes", true), ("colTypmods", true), ("colCollations", true), ("groupClauses", true)]),
        (16 | 18, "SETTODEFAULT") => (&["typeId", "typeMod", "collation", "location"], &[("typeId", Type, false), ("collation", Collation, false)], &[]),
        (16, "SORTGROUPCLAUSE") => (&["tleSortGroupRef", "eqop", "sortop", "nulls_first", "hashable"], &[("eqop", Operator, false), ("sortop", Operator, false)], &[]),
        (18, "SORTGROUPCLAUSE") => (&["tleSortGroupRef", "eqop", "sortop", "reverse_sort", "nulls_first", "hashable"], &[("eqop", Operator, false), ("sortop", Operator, false)], &[]),
        (16 | 18, "SQLVALUEFUNCTION") => (&["op", "type", "typmod", "location"], &[("type", Type, false)], &[]),
        (16 | 18, "SUBLINK") => (&["subLinkType", "subLinkId", "testexpr", "operName", "subselect", "location"], &[], &[("testexpr", false), ("operName", true), ("subselect", false)]),
        (16 | 18, "TABLESAMPLECLAUSE") => (&["tsmhandler", "args", "repeatable"], &[("tsmhandler", Routine, false)], &[("args", true), ("repeatable", false)]),
        (16 | 18, "TARGETENTRY") => (&["expr", "resno", "resname", "ressortgroupref", "resorigtbl", "resorigcol", "resjunk"], &[("resorigtbl", Relation, false)], &[("expr", false)]),
        (16, "VAR") => (&["varno", "varattno", "vartype", "vartypmod", "varcollid", "varnullingrels", "varlevelsup", "varnosyn", "varattnosyn", "location"], &[("vartype", Type, false), ("varcollid", Collation, false)], &[("varnullingrels", true)]),
        (18, "VAR") => (&["varno", "varattno", "vartype", "vartypmod", "varcollid", "varnullingrels", "varlevelsup", "varreturningtype", "varnosyn", "varattnosyn", "location"], &[("vartype", Type, false), ("varcollid", Collation, false)], &[("varnullingrels", true)]),
        (16, "WINDOWCLAUSE") => (&["name", "refname", "partitionClause", "orderClause", "frameOptions", "startOffset", "endOffset", "runCondition", "startInRangeFunc", "endInRangeFunc", "inRangeColl", "inRangeAsc", "inRangeNullsFirst", "winref", "copiedOrder"], &[("startInRangeFunc", Routine, false), ("endInRangeFunc", Routine, false), ("inRangeColl", Collation, false)], &[("partitionClause", true), ("orderClause", true), ("startOffset", false), ("endOffset", false), ("runCondition", true)]),
        (18, "WINDOWCLAUSE") => (&["name", "refname", "partitionClause", "orderClause", "frameOptions", "startOffset", "endOffset", "startInRangeFunc", "endInRangeFunc", "inRangeColl", "inRangeAsc", "inRangeNullsFirst", "winref", "copiedOrder"], &[("startInRangeFunc", Routine, false), ("endInRangeFunc", Routine, false), ("inRangeColl", Collation, false)], &[("partitionClause", true), ("orderClause", true), ("startOffset", false), ("endOffset", false)]),
        (16, "WINDOWFUNC") => (&["winfnoid", "wintype", "wincollid", "inputcollid", "args", "aggfilter", "winref", "winstar", "winagg", "location"], &[("winfnoid", Routine, false), ("wintype", Type, false), ("wincollid", Collation, false), ("inputcollid", Collation, false)], &[("args", true), ("aggfilter", false)]),
        (18, "WINDOWFUNC") => (&["winfnoid", "wintype", "wincollid", "inputcollid", "args", "aggfilter", "runCondition", "winref", "winstar", "winagg", "location"], &[("winfnoid", Routine, false), ("wintype", Type, false), ("wincollid", Collation, false), ("inputcollid", Collation, false)], &[("args", true), ("aggfilter", false), ("runCondition", true)]),
        _ => return None,
    };
    Some(Specification { fields, references, children })
}
